// === Tab: mySketch.js ===
// Author: tomxor. Translated and extended from https://www.dwitter.net/d/10534
// Original one-liner x.fillRect(0,0,i=2e3,i);for(t+=160;p=i&1,m=t/C(t/i)+p*(t/2+i%t),i--;);x.clearRect(960+m*S(n=t/9+i*i)*C(!p*i/t),540+m*C(n+p*2),s=3-C(n)*3,s)

// 元作者：tomxor 氏
// このスケッチは、「Dwitter」で投稿されている作品を読みやすく、かつ画面サイズに合わせて動くように翻訳・拡張したものです。
// 元作品URL: https://www.dwitter.net/d/10534
// 元の1行のコード：x.fillRect(0,0,i=2e3,i);for(t+=160;p=i&1,m=t/C(t/i)+p*(t/2+i%t),i--;);x.clearRect(960+m*S(n=t/9+i*i)*C(!p*i/t),540+m*C(n+p*2),s=3-C(n)*3,s)


let counter = 100;
let parity_flag = 0;

function setup() {
	createCanvas(windowWidth, windowHeight);
	stroke(255);
	describe("An animated rendering of Saturn-like planet, viewed from space with a tilted ring system, " +
		"created using densely plotted points that vary in size to simulate 3D shading and rotation over time.")
}

function draw() {
	background(0);
	counter += 0.01;

	for (let i = 2000; i >= 0; i -= 2) { // i が「偶数」のときだけループ：土星の本体（球体）を描く
		parity_flag = 0; // フラグを 0（false）にして、本体モードに切り替え
		drawPoints(i);
	}
	for (let i = 1999; i > 0; i -= 2) { // i が「奇数」のときだけループ：土星の周りの輪っかを描く
		parity_flag = 1;
		drawPoints(i);
	}

	function drawPoints(i) {
		let radial_offset = counter / cos(counter / i) + parity_flag * (counter / 2 + i % counter);
		// 1. 中心からの距離（半径）を計算。parity_flag が 0なら「球体の半径」、1なら「輪（リング）の半径」を計算している。

		let angular_phase = counter / 9 + i * i; 
		// 2. 回転の角度を計算。 counter（時間）を使って、全体がゆっくり宇宙で自転するような角度を作っている。

		let x_position = (windowWidth / 2 - 100) + radial_offset * sin(angular_phase) * cos(!parity_flag * i / counter);
		// 3. 画面の横位置（X座標）を計算。　画面の中心を基準にして、サイン波（sin）を使って点を左右に振り分けている。

		let y_position = 400 + radial_offset * cos(angular_phase + parity_flag * 2);
		// 4. 画面の縦位置（Y座標）を計算。　「輪」の時だけ角度をズラす（+ parity_flag * 2）ことで、輪が斜めに傾いて見える。

		let point_size = 1 - cos(angular_phase);
		// 5. 点の大きさを計算（これで光と影の立体感を出す）。　角度（angular_phase）に合わせて大きさを「0 〜 2」の間で変化させる。
		// これにより、手前にある点は大きく（明るく）、奥や影になる点は小さく（暗く）なります。


		strokeWeight(point_size);
		point(x_position, y_position);
		// 6. 決定したサイズと位置で「点」を打つ
	}
}

